<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$id=(int)$_GET['id'];$st=$pdo->prepare('SELECT e.*,c.nome cliente,u.nome usuario_nome FROM encomendas e JOIN clientes c ON c.id=e.cliente_id LEFT JOIN usuarios u ON u.id=e.usuario_id WHERE e.id=?');$st->execute([$id]);$eRow=$st->fetch();$it=$pdo->prepare('SELECT ei.*,p.nome FROM encomenda_itens ei JOIN produtos p ON p.id=ei.produto_id WHERE ei.encomenda_id=?');$it->execute([$id]);$items=$it->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="no-print page-head"><h1>Impressão da encomenda</h1><button class="btn primary" onclick="printPage()">Imprimir</button></div><div class="card"><div class="print-header"><h1><?=e(setting('nome_livraria',APP_NAME))?></h1><div class="print-small"><?=e(setting('endereco_livraria'))?> · <?=e(setting('telefone_livraria'))?></div></div><h2>Encomenda <?=e($eRow['numero'])?></h2><p><strong>Data:</strong> <?=datetime_br($eRow['data_hora'])?> · <strong>Cliente:</strong> <?=e($eRow['cliente'])?> · <strong>Origem:</strong> <?=e($eRow['origem'])?></p><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço unitário</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['nome'])?></td><td><?=e($i['quantidade'])?></td><td><?=money($i['preco_unitario'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="total-line"><span>Desconto</span><strong><?=money($eRow['desconto'])?></strong></div><div class="total-line total"><span>Total</span><strong><?=money($eRow['total'])?></strong></div><p><strong>Status:</strong> <?=e($eRow['status'])?></p><p><strong>Observações:</strong> <?=nl2br(e($eRow['observacoes']))?></p><p><strong>Usuário responsável:</strong> <?=e($eRow['usuario_nome'])?></p></div><?php include __DIR__.'/../../includes/footer.php'; ?>
